"use client";

import * as React from "react";
import { Link2, PanelLeftIcon, Plus } from "lucide-react";

import { cn } from "@/lib/utils";
import { useCalendar } from "@/components/calendar-provider";
import { useScheduling } from "@/components/scheduling-provider";
import { CalendarList } from "@/components/calendar-list";
import { CalendarSidebarPeople } from "@/components/calendar-sidebar-people";
import { MiniCalendar } from "@/components/mini-calendar";
import {
  CALENDAR_SIDEBAR_COLORS_CLASS,
  SidebarOverlay,
} from "@/components/sidebar-overlay";
import { ThemeToggle } from "@/components/theme-toggle";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Kbd } from "@/components/ui/kbd";
import {
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupContent,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarSeparator,
} from "@/components/ui/sidebar";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { getPeriodStart } from "@/lib/event-utils";
import type { SchedulingLinkKind } from "@/components/calendar-types";

/** Width of the calendar sidebar, inline and as an overlay */
export const CALENDAR_SIDEBAR_WIDTH = "15rem";

/** No days to highlight: month view and the agenda */
const NO_VISIBLE_DAYS: Date[] = [];

/** Shortcut hint inside a menu item: the key without its cap, as the view menu shows them */
const MENU_KBD_CLASS =
  "ml-auto h-auto min-w-0 rounded-none bg-transparent px-0";

interface CalendarSidebarProps {
  /** Whether the sidebar shows. Defaults to true */
  open?: boolean;
  /** Called when the overlay asks to close (outside tap, Escape, close button, a day picked) */
  onOpenChange?: (open: boolean) => void;
  /** Render as a modal sheet instead of an inline column (phones) */
  overlay?: boolean;
  /** Buttons shown in the footer before the theme toggle, e.g. links */
  footerActions?: React.ReactNode;
  /** Ids of the hidden calendars (controlled), see `CalendarList` */
  hiddenCalendarIds?: string[];
  /** Ids of the calendars hidden at first (uncontrolled) */
  defaultHiddenCalendarIds?: string[];
  /** Called with the new hidden ids when a calendar is shown or hidden */
  onHiddenCalendarIdsChange?: (hiddenCalendarIds: string[]) => void;
  /** Adds "Add calendar account" below the calendars, which calls it */
  onAddCalendarAccount?: () => void;
  /** Classes for the inline sidebar's fixed column */
  className?: string;
}

/**
 * Notion Calendar's left sidebar: the mini calendar, scheduling, the
 * "Meet with..." field with the people you meet with and the teammates
 * shown, the calendar list and a theme toggle. Inline it's a fixed column that pushes
 * the page over; with `overlay` it's a sheet from the left. Reads the
 * calendar's date and view from the nearest `CalendarProvider`, and needs
 * shadcn/ui's `SidebarProvider` around it. The Scheduling row shows inside
 * a `SchedulingProvider`. "Add calendar account" shows when you pass
 * `onAddCalendarAccount`.
 */
export function CalendarSidebar({
  open = true,
  onOpenChange,
  overlay = false,
  footerActions,
  hiddenCalendarIds,
  defaultHiddenCalendarIds,
  onHiddenCalendarIdsChange,
  onAddCalendarAccount,
  className,
}: CalendarSidebarProps) {
  const {
    view,
    currentDate,
    displayMonth,
    visibleDays,
    weekStartsOn,
    numberOfDays,
    viewSettings,
    goToDate,
  } = useCalendar();
  const scheduling = useScheduling();

  const sidebarStyle = {
    "--sidebar-width": CALENDAR_SIDEBAR_WIDTH,
  } as React.CSSProperties;

  /** Mini calendar day pick: go to its period, and get the overlay out of the way */
  const handleDateSelect = (date: Date) => {
    goToDate(getPeriodStart(date, view, weekStartsOn, numberOfDays));
    if (overlay) onOpenChange?.(false);
  };

  const content = (
    <>
      {/* Spacing set here, not left to the shadcn/ui style (nova has none) */}
      <SidebarContent className="gap-2">
        <SidebarGroup className="px-0">
          <SidebarGroupContent>
            <MiniCalendar
              onDateSelect={handleDateSelect}
              currentDate={
                view === "month" && displayMonth ? displayMonth : currentDate
              }
              visibleDays={
                view === "month" || view === "agenda"
                  ? NO_VISIBLE_DAYS
                  : visibleDays
              }
              weekStartsOn={weekStartsOn}
              showWeekNumber={viewSettings.showWeekNumbers}
            />
          </SidebarGroupContent>
        </SidebarGroup>
        {/* Scheduling Section: only inside a SchedulingProvider */}
        {scheduling && (
          <SidebarGroup className="py-0">
            <SidebarGroupContent>
              <SidebarMenu className="gap-1">
                <SidebarMenuItem>
                  <CalendarSidebarScheduling
                    onStart={() => {
                      if (overlay) onOpenChange?.(false);
                    }}
                  />
                </SidebarMenuItem>
              </SidebarMenu>
            </SidebarGroupContent>
          </SidebarGroup>
        )}
        {/* "Meet with...", meeting participants and team calendars */}
        <CalendarSidebarPeople />
        <CalendarList
          hiddenCalendarIds={hiddenCalendarIds}
          defaultHiddenCalendarIds={defaultHiddenCalendarIds}
          onHiddenCalendarIdsChange={onHiddenCalendarIdsChange}
        />
        {onAddCalendarAccount && (
          <>
            <SidebarSeparator className="mx-0" />
            <SidebarGroup className="py-0">
              <SidebarGroupContent>
                <SidebarMenu className="gap-1">
                  <SidebarMenuItem>
                    <SidebarMenuButton
                      className="text-calendar-sidebar-muted-foreground hover:text-sidebar-foreground gap-1.5 text-sm rounded-sm"
                      onClick={onAddCalendarAccount}
                    >
                      <Plus className="size-4" />
                      <span className="min-w-0 flex-1 truncate">
                        Add calendar account
                      </span>
                    </SidebarMenuButton>
                  </SidebarMenuItem>
                </SidebarMenu>
              </SidebarGroupContent>
            </SidebarGroup>
          </>
        )}
      </SidebarContent>
      <SidebarFooter className="border-t border-sidebar-border">
        <div className="flex items-center justify-start gap-1 px-2 py-2">
          {footerActions}
          <Tooltip>
            <TooltipTrigger asChild>
              <ThemeToggle className="text-sidebar-foreground" />
            </TooltipTrigger>
            <TooltipContent side="top">
              Toggle theme <Kbd className="ml-1">shift</Kbd> <Kbd>M</Kbd>
            </TooltipContent>
          </Tooltip>
        </div>
      </SidebarFooter>
    </>
  );

  if (overlay) {
    return (
      <SidebarOverlay
        open={open}
        onOpenChange={(next) => onOpenChange?.(next)}
        side="left"
        title="Calendar sidebar"
        description="Mini calendar, scheduling and calendar list."
        style={sidebarStyle}
      >
        {/* Same height and position as the header toggle, so tapping the same spot closes it */}
        <div className="flex h-14 shrink-0 items-center pl-2">
          <Button
            variant="ghost"
            size="icon"
            className="size-7 text-muted-foreground"
            onClick={() => onOpenChange?.(false)}
          >
            <PanelLeftIcon />
            <span className="sr-only">Close calendar sidebar</span>
          </Button>
        </div>
        {content}
      </SidebarOverlay>
    );
  }

  return (
    <div
      data-state={open ? "expanded" : "collapsed"}
      className={cn(
        CALENDAR_SIDEBAR_COLORS_CLASS,
        "text-sidebar-foreground group peer hidden md:block",
      )}
      style={sidebarStyle}
    >
      {/* Gap element that handles the space transition */}
      <div
        className={cn(
          "relative bg-transparent",
          open ? "w-(--sidebar-width)" : "w-0",
        )}
      />
      {/* Sidebar container */}
      <div
        className={cn(
          "bg-sidebar fixed inset-y-0 left-0 z-10 hidden h-svh w-(--sidebar-width) flex-col border-r md:flex",
          open ? "left-0" : "left-[calc(var(--sidebar-width)*-1)]",
          className,
        )}
      >
        {content}
      </div>
    </div>
  );
}

/** Props of the Scheduling row (only used in this file) */
interface CalendarSidebarSchedulingProps {
  /** Called once marking open times starts, e.g. to close the overlay */
  onStart: () => void;
}

/**
 * The sidebar's Scheduling row. It starts marking open times to share
 * (the S key does too), and leaves again while they're being marked. When
 * the app creates scheduling links, it opens a menu instead: share
 * availability, or create a recurring or one-off link.
 */
function CalendarSidebarScheduling({
  onStart,
}: CalendarSidebarSchedulingProps) {
  const scheduling = useScheduling();
  if (!scheduling) return null;
  const { isPicking, canCreateLinks, startPicking, cancelPicking } = scheduling;

  const shareAvailability = () => {
    startPicking();
    onStart();
  };

  const createLink = (kind: SchedulingLinkKind) => {
    scheduling.createSchedulingLink(kind);
    onStart();
  };

  const rowContent = (
    <>
      <Link2 className="size-4 text-calendar-sidebar-muted-foreground" />
      <span className="min-w-0 flex-1 truncate text-sm">Scheduling</span>
    </>
  );

  if (isPicking || !canCreateLinks) {
    return (
      <Tooltip>
        <TooltipTrigger asChild>
          <SidebarMenuButton
            isActive={isPicking}
            aria-pressed={isPicking}
            className="text-sidebar-foreground rounded-sm"
            onClick={isPicking ? cancelPicking : shareAvailability}
          >
            {rowContent}
          </SidebarMenuButton>
        </TooltipTrigger>
        <TooltipContent side="right">
          {isPicking ? (
            <>
              Stop sharing availability <Kbd className="ml-1">esc</Kbd>
            </>
          ) : (
            <>
              Share availability <Kbd className="ml-1">S</Kbd>
            </>
          )}
        </TooltipContent>
      </Tooltip>
    );
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <SidebarMenuButton className="text-sidebar-foreground rounded-sm">
          {rowContent}
        </SidebarMenuButton>
      </DropdownMenuTrigger>
      <DropdownMenuContent side="right" align="start" className="w-56">
        <DropdownMenuItem onClick={shareAvailability}>
          Share availability
          <Kbd className={MENU_KBD_CLASS}>S</Kbd>
        </DropdownMenuItem>
        <DropdownMenuSeparator />
        <DropdownMenuItem onClick={() => createLink("recurring")}>
          Create recurring link
        </DropdownMenuItem>
        <DropdownMenuItem onClick={() => createLink("one-off")}>
          Create one-off link
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

"use client";

import * as React from "react";
import { History, Rss, UserRound, X } from "lucide-react";

import { cn } from "@/lib/utils";
import { useCalendarPeople } from "@/components/calendar-people";
import type { CalendarPerson, EventContact } from "@/components/calendar-types";
import {
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarMenu,
  SidebarMenuItem,
} from "@/components/ui/sidebar";
import { getEventColorStyle } from "@/lib/event-utils";
import {
  getPersonInitial,
  getPersonName,
  getTypedPerson,
  isSameEmail,
  suggestPeople,
} from "@/lib/people";

/** A person's swatch, as the calendar list colors its calendars: their color, set with `getEventColorStyle()` */
const PERSON_SWATCH_CLASS = "bg-event";

/** A person row's name: the sidebar's small text, truncated */
const PERSON_ROW_NAME_CLASS =
  "min-w-0 flex-1 truncate text-xs text-sidebar-foreground";

/** A person row's remove button: shown on hover or keyboard focus */
const PERSON_ROW_REMOVE_CLASS =
  "text-calendar-sidebar-muted-foreground hover:bg-sidebar-accent focus-visible:ring-sidebar-ring inline-flex size-6 shrink-0 items-center justify-center rounded-sm opacity-0 outline-none group-hover/person:opacity-100 focus-visible:opacity-100 focus-visible:ring-2";

/** Header of a people section ("Meeting participants", "Team calendars") */
const PEOPLE_SECTION_LABEL_CLASS =
  "text-sidebar-foreground/70 h-7 rounded-sm px-2 text-xs";

/**
 * The sidebar's people, as in Notion Calendar: the "Meet with..." field,
 * then the people you're meeting with ("Meeting participants") and the
 * teammates whose calendars show ("Team calendars"), each removable. Reads
 * and changes them through `useCalendarPeople()`, so it goes inside
 * `CalendarProvider`.
 */
export function CalendarSidebarPeople() {
  const {
    contacts,
    meetWith,
    teammates,
    shownPeople,
    addMeetWith,
    removeMeetWith,
    clearMeetWith,
    removeTeammate,
  } = useCalendarPeople();
  const meetingPeople = shownPeople.filter((person) =>
    meetWith.some((email) => isSameEmail(email, person.email)),
  );
  const teamPeople = shownPeople.filter((person) =>
    teammates.some((email) => isSameEmail(email, person.email)),
  );

  return (
    <>
      <SidebarGroup className="px-2 py-2">
        <MeetWithField
          contacts={contacts}
          exclude={meetWith}
          onPick={addMeetWith}
        />
      </SidebarGroup>
      {meetingPeople.length > 0 && (
        <SidebarGroup className="py-0">
          <SidebarGroupLabel className={PEOPLE_SECTION_LABEL_CLASS}>
            Meeting participants
            <button
              type="button"
              className="text-calendar-sidebar-muted-foreground hover:text-sidebar-foreground focus-visible:ring-sidebar-ring ml-auto rounded-sm px-1 text-xs outline-none focus-visible:ring-2"
              onClick={clearMeetWith}
            >
              Clear
            </button>
          </SidebarGroupLabel>
          <SidebarGroupContent>
            <SidebarMenu className="gap-0">
              {meetingPeople.map((person) => (
                <PersonRow
                  key={person.email}
                  person={person}
                  shape="square"
                  removeLabel={`Stop meeting with ${getPersonName(person)}`}
                  onRemove={() => removeMeetWith(person.email)}
                />
              ))}
            </SidebarMenu>
          </SidebarGroupContent>
        </SidebarGroup>
      )}
      {teamPeople.length > 0 && (
        <SidebarGroup className="py-0">
          <SidebarGroupLabel className={PEOPLE_SECTION_LABEL_CLASS}>
            Team calendars
          </SidebarGroupLabel>
          <SidebarGroupContent>
            <SidebarMenu className="gap-0">
              {teamPeople.map((person) => (
                <PersonRow
                  key={person.email}
                  person={person}
                  shape="round"
                  removeLabel={`Remove ${getPersonName(person)} from team calendars`}
                  onRemove={() => removeTeammate(person.email)}
                />
              ))}
            </SidebarMenu>
          </SidebarGroupContent>
        </SidebarGroup>
      )}
    </>
  );
}

interface PersonRowProps {
  person: CalendarPerson;
  /** A square with a feed glyph (meeting participants) or a round initial (teammates) */
  shape: "square" | "round";
  /** Accessible name of the remove button */
  removeLabel: string;
  onRemove: () => void;
}

/** One person in a sidebar people section: their color, name and a remove button */
function PersonRow({ person, shape, removeLabel, onRemove }: PersonRowProps) {
  const name = getPersonName(person);
  return (
    <SidebarMenuItem
      data-person-row={person.email}
      className="group/person hover:bg-sidebar-accent flex h-7 items-center gap-2 rounded-sm pr-1 pl-2"
      title={person.name ? `${person.name} (${person.email})` : person.email}
    >
      {shape === "square" ? (
        <span
          aria-hidden
          className={cn(
            "flex size-3 shrink-0 items-center justify-center rounded-xs",
            PERSON_SWATCH_CLASS,
          )}
          style={getEventColorStyle(person.color)}
        >
          <Rss className="size-2 text-event-foreground" />
        </span>
      ) : (
        <span
          aria-hidden
          className={cn(
            "flex size-4 shrink-0 items-center justify-center rounded-full text-[9px] leading-none font-semibold text-event-foreground",
            PERSON_SWATCH_CLASS,
          )}
          style={getEventColorStyle(person.color)}
        >
          {getPersonInitial(person)}
        </span>
      )}
      <span className={PERSON_ROW_NAME_CLASS}>{name}</span>
      <button
        type="button"
        aria-label={removeLabel}
        className={PERSON_ROW_REMOVE_CLASS}
        onClick={onRemove}
      >
        <X className="size-3.5" />
      </button>
    </SidebarMenuItem>
  );
}

interface MeetWithFieldProps {
  /** People it offers */
  contacts: EventContact[];
  /** Emails it leaves out: the people met with already */
  exclude: string[];
  /** Called with the picked person's email */
  onPick: (email: string) => void;
}

/**
 * Notion Calendar's "Meet with..." field: focusing it lists recent people,
 * typing lists the matches (or the typed address), arrows move through
 * them, Enter or a click picks one. Escape closes the list and clears the
 * text, without reaching the calendar's own Escape.
 */
function MeetWithField({ contacts, exclude, onPick }: MeetWithFieldProps) {
  const inputRef = React.useRef<HTMLInputElement>(null);
  const listId = React.useId();
  const [query, setQuery] = React.useState("");
  const [open, setOpen] = React.useState(false);
  const [activeIndex, setActiveIndex] = React.useState(-1);
  const trimmed = query.trim();

  const options = React.useMemo<EventContact[]>(() => {
    const matches = suggestPeople(contacts, trimmed, exclude);
    const typed = getTypedPerson(contacts, trimmed, exclude);
    return typed ? [...matches, typed] : matches;
  }, [contacts, exclude, trimmed]);

  const listOpen = open && options.length > 0;

  // While typing, the first match is active, as in Notion
  React.useEffect(() => {
    setActiveIndex(trimmed ? 0 : -1);
  }, [trimmed]);

  const pick = (contact: EventContact) => {
    onPick(contact.email);
    setQuery("");
    setOpen(false);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Escape") {
      // Closing the list (or clearing the text) is all Escape does here
      e.stopPropagation();
      if (listOpen || query) {
        setOpen(false);
        setQuery("");
        return;
      }
      inputRef.current?.blur();
      return;
    }
    if (e.key === "ArrowDown" || e.key === "ArrowUp") {
      e.preventDefault();
      if (!listOpen) {
        setOpen(true);
        return;
      }
      const step = e.key === "ArrowDown" ? 1 : -1;
      setActiveIndex((index) => {
        if (index === -1) return step === 1 ? 0 : options.length - 1;
        return (index + step + options.length) % options.length;
      });
      return;
    }
    if (e.key === "Enter") {
      e.preventDefault();
      const option = options[activeIndex];
      if (listOpen && option) pick(option);
    }
  };

  const activeId =
    listOpen && activeIndex >= 0 ? `${listId}-${activeIndex}` : undefined;

  return (
    <div className="relative">
      <div
        // Filled with the sidebar's border color: half strength at rest, full
        // while focused. A dark theme fills it only while focused
        className="flex items-center gap-2 rounded-sm bg-sidebar-border/50 px-2 py-1.5 has-[:focus]:bg-sidebar-border dark:bg-sidebar dark:has-[:focus]:bg-sidebar-accent"
        onClick={() => inputRef.current?.focus()}
      >
        <UserRound className="text-calendar-sidebar-muted-foreground size-4 shrink-0" />
        <input
          ref={inputRef}
          type="text"
          role="combobox"
          aria-label="Meet with"
          aria-expanded={listOpen}
          aria-controls={listId}
          aria-autocomplete="list"
          aria-activedescendant={activeId}
          placeholder="Meet with..."
          autoComplete="off"
          value={query}
          className="text-sidebar-foreground placeholder:text-calendar-sidebar-muted-foreground min-w-0 flex-1 bg-transparent text-sm outline-none"
          onChange={(e) => {
            setQuery(e.target.value);
            setOpen(true);
          }}
          onFocus={() => setOpen(true)}
          onBlur={() => {
            setOpen(false);
            setQuery("");
          }}
          onKeyDown={handleKeyDown}
        />
      </div>
      <div
        id={listId}
        role="listbox"
        aria-label="People"
        hidden={!listOpen}
        className="bg-popover text-popover-foreground absolute inset-x-0 top-full z-50 mt-1 overflow-hidden rounded-md border p-1 shadow-md"
      >
        {listOpen &&
          options.map((contact, index) => (
            <div
              key={contact.email}
              id={`${listId}-${index}`}
              role="option"
              aria-selected={index === activeIndex}
              className={cn(
                "flex cursor-default items-center gap-2 rounded-sm px-2 py-1.5 text-xs",
                index === activeIndex && "bg-accent text-accent-foreground",
              )}
              // Keeps the focus in the field, so its blur doesn't close the list first
              onMouseDown={(e) => e.preventDefault()}
              onMouseEnter={() => setActiveIndex(index)}
              onClick={() => pick(contact)}
            >
              <span className="flex min-w-0 flex-1 flex-col">
                <span className="truncate">{getPersonName(contact)}</span>
                {contact.name && (
                  <span className="text-muted-foreground truncate text-[11px]">
                    {contact.email}
                  </span>
                )}
              </span>
              {!trimmed && contact.recent && (
                <History
                  aria-label="Recent"
                  className="text-muted-foreground size-3.5 shrink-0"
                />
              )}
            </div>
          ))}
      </div>
    </div>
  );
}
